function settings(){return '<main class="section"><div class="eyebrow">CONNECTION</div><h1 class="page-title">კავშირის <span>პარამეტრები.</span></h1><p class="muted intro">Android Emulator-ისთვის გამოიყენე http://10.0.2.2:8000. ფიზიკურ ტელეფონზე მიუთითე კომპიუტერის LAN IP ან HTTPS დომენი.</p><form id="settings-form" class="form-stack"><label>API მისამართი<input name="apiBase" type="url" required value="'+esc(state.apiBase)+'" placeholder="http://10.0.2.2:8000"></label><button class="primary-btn">შენახვა და შემოწმება</button><p id="settings-note" class="form-note"></p></form><div class="notice">სერვერი უნდა იყოს გაშვებული და ხელმისაწვდომი იმავე ქსელიდან.</div></main>'}

function adminPage(){
if(!state.user || !state.user.is_admin)return '<main class="section"><h1 class="page-title">წვდომა <span>შეზღუდულია.</span></h1><p class="muted">ადმინისტრატორის უფლებები არ გაქვს.</p><button class="secondary-btn" data-action="account">პროფილზე დაბრუნება</button></main>';
if(state.adminLoading)return '<main class="section"><div class="eyebrow">MOTOHUB / ADMIN</div><h1 class="page-title">ადმინისტრაცია<span>.</span></h1><p class="muted">მონაცემები იტვირთება…</p></main>';
if(state.adminError)return '<main class="section"><div class="eyebrow">MOTOHUB / ADMIN</div><h1 class="page-title">ადმინისტრაცია<span>.</span></h1><div class="error-state">'+esc(state.adminError)+'</div><button class="primary-btn" data-action="admin-refresh">ხელახლა ცდა</button></main>';
const d=state.adminData;if(!d)return '<main class="section"><h1 class="page-title">ადმინისტრაცია<span>.</span></h1><button class="primary-btn" data-action="admin-refresh">მონაცემების ჩატვირთვა</button></main>';
const counts=d.counts||{};
const countCards=[['pending_motorcycles','მოტო განცხადებები დასამტკიცებლად'],['published_motorcycles','გამოქვეყნებული მოტოები'],['open_part_requests','ნაწილების მოთხოვნები'],['pending_rental_bookings','გაქირავების ჯავშნები'],['pending_service_bookings','სერვისის ჯავშნები'],['pending_service_centers','სერვისცენტრები დასამტკიცებლად']];
const section=(title,type,items,actions)=>'<section class="admin-section"><div class="section-heading"><h2>'+title+'</h2><span class="pill">'+items.length+'</span></div>'+(items.length?items.map(x=>'<article class="admin-item"><strong>'+esc(x.title||x.part_name||'მოთხოვნა')+'</strong><p>'+esc(x.owner||x.customer_name||x.center||'')+(x.email?' · '+esc(x.email):'')+'</p>'+(x.motorcycle?'<p class="muted">'+esc(x.motorcycle)+'</p>':'')+(x.phone?'<p class="muted">'+esc(x.phone)+'</p>':'')+(x.start_date?'<p class="muted">'+esc(x.start_date)+' — '+esc(x.end_date)+' · '+money(x.total_price)+'</p>':'')+(x.scheduled_at?'<p class="muted">'+esc(formatDateTime(x.scheduled_at))+'</p>':'')+(x.price!=null?'<p class="muted">'+money(x.price)+'</p>':'')+(x.details?'<p class="muted">'+esc(x.details)+'</p>':'')+'<p class="admin-status">სტატუსი: '+esc(statusLabel(x.status))+'</p><div class="admin-actions">'+(type==='motorcycles'&&x.status==='published'?(x.is_featured?[['unfeatured','გამორჩეულიდან მოხსნა']]:[['featured','გამორჩეულად მონიშვნა']]):actions).map(a=>'<button class="secondary-btn" data-action="admin-status" data-type="'+type+'" data-id="'+x.id+'" data-status="'+a[0]+'">'+a[1]+'</button>').join('')+'</div></article>').join(''):'<p class="muted">ამ განყოფილებაში ახალი ჩანაწერი არ არის.</p>')+'</section>';
return '<main class="section admin-page"><div class="eyebrow">MOTOHUB / CONTROL CENTER</div><h1 class="page-title">ადმინისტრაცია<span>.</span></h1><p class="muted intro">მართე განცხადებები, მოთხოვნები და ჯავშნები პირდაპირ აპიდან.</p><button class="text-button" data-action="admin-refresh">↻ განახლება</button><div class="admin-counts">'+countCards.map(c=>'<div class="admin-count"><strong>'+Number(counts[c[0]]||0)+'</strong><small>'+c[1]+'</small></div>').join('')+'</div>'+section('მოტოციკლების დამტკიცება','motorcycles',d.motorcycles||[],[['published','გამოქვეყნება'],['rejected','უარყოფა']])+section('გამოქვეყნებული მოტოციკლები','motorcycles',d.published_motorcycles||[],[])+section('ნაწილების მოთხოვნები','part-requests',d.part_requests||[],[['in_progress','მუშავდება'],['completed','დასრულდა'],['rejected','უარყოფა']])+section('გაქირავების ჯავშნები','rental-bookings',d.rental_bookings||[],[['confirmed','დადასტურება'],['declined','უარყოფა'],['completed','დასრულდა']])+section('სერვისცენტრების განაცხადები','service-centers',d.service_centers||[],[['approved','დამტკიცება'],['rejected','უარყოფა']])+section('სერვისის ჯავშნები','service-bookings',d.service_bookings||[],[['confirmed','დადასტურება'],['declined','უარყოფა'],['completed','დასრულდა']])+'</main>';
}
async function loadAdmin(){if(state.page!=='admin')return;state.adminLoading=true;state.adminError='';render();try{state.adminData=await api('/api/mobile/admin/dashboard')}catch(e){state.adminError=e.message||'ადმინისტრაციის მონაცემების ჩატვირთვა ვერ მოხერხდა.'}finally{state.adminLoading=false;if(state.page==='admin')render()}}
async function updateAdminStatus(type,id,status){if(!confirm('ნამდვილად გსურს სტატუსის შეცვლა?'))return;try{await api('/api/mobile/admin/'+encodeURIComponent(type)+'/'+encodeURIComponent(id)+'/status',{method:'PATCH',body:JSON.stringify({status})});state.adminData=null;await loadAdmin()}catch(e){alert(e.message)}}


