 if(state.page==='messages'){
  return featureShell('messages','<details class="feature-group" open><summary><span>01</span><b>ახალი მიმოწერა</b><small>შეტყობინების გაგზავნა</small></summary><div class="feature-group-body"><section class="account-panel"><h3>ახალი მიმოწერის დაწყება</h3><form id="conversation-form" class="form-stack" data-feature-form data-endpoint="/api/mobile/conversations"><label>მიმღების მომხმარებლის ID<input name="recipient_id" type="number" min="1" required value="'+esc(state.messageRecipientId||'')+'"></label><label>მოტოციკლის ID (არასავალდებულო)<input name="motorcycle_id" type="number" min="1" value="'+esc(state.messageMotorcycleId||'')+'"></label><label>შეტყობინება<textarea name="body" required maxlength="5000"></textarea></label><button class="primary-btn">გაგზავნა</button><p class="form-note" id="conversation-form-note"></p></form></section></div></details><details class="feature-group"><summary><span>02</span><b>ჩემი მიმოწერები</b><small>'+((d.conversations||[]).length)+' საუბარი</small></summary><div class="feature-group-body"><section class="account-panel"><h3>ჩემი მიმოწერები</h3>'+((d.conversations||[]).map(x=>'<button class="notice full-width" data-action="open-conversation" data-id="'+x.id+'"><strong>'+esc(x.subject||'პირადი მიმოწერა')+'</strong><p>'+esc(x.latest_message?.body||'')+'</p><small>წაუკითხავი: '+Number(x.unread_count||0)+'</small></button>').join('')||'<p class="muted">მიმოწერები ჯერ არ არის.</p>')+'</section></div></details>')
 }
